// Indian Tourism Seed Data for TravelSaathi AI

export interface SeedState {
  name: string;
  code: string;
  capital: string;
  region: string;
  description: string;
  image_url: string;
}

export interface SeedCity {
  name: string;
  state_code: string;
  description: string;
  cover_image: string;
  latitude: number;
  longitude: number;
  categories: string[];
  is_featured: boolean;
}

export interface SeedPlace {
  cityName: string;
  name: string;
  description: string;
  cover_image: string;
  category: string;
  address: string;
  latitude: number;
  longitude: number;
  opening_time: string;
  closing_time: string;
  entry_fee: number;
  best_visiting_time: string;
  recommended_duration_hours: number;
  rating: number;
  review_count: number;
  family_friendly: boolean;
  couple_friendly: boolean;
  solo_friendly: boolean;
  budget_friendly: boolean;
  is_premium: boolean;
  is_featured: boolean;
  ai_priority: number;
}

export interface SeedHiddenGem {
  cityName: string;
  name: string;
  description: string;
  photos: string[];
  category: string;
  location: string;
  best_time: string;
  duration_hours: number;
  entry_fee: number;
  distance_from_city_km: number;
  route_info: string;
  rating: number;
  is_featured: boolean;
}

